    def spans(length, dividers):
        out, start = [], 0
        for d in dividers:
            if d >= start:
                out.append((start, d))
                start = d + 1
        if start < length:
            out.append((start, length))
        # Keep only full-size panels; partial edge remnants are not cells of the tiling.
        sizes = [b - x for x, b in out]
        full = max(set(sizes), key=sizes.count)
        return [(x, b) for x, b in out if b - x == full]

    rs = spans(h, hlines)
    cs = spans(w, vlines)
    original = [row[:] for row in grid]
    # Each original nonempty panel is reflected once across each immediately
    # adjacent divider. Use a snapshot so copies do not cascade across panels.
    for ri, (r0, r1) in enumerate(rs):
        for ci, (c0, c1) in enumerate(cs):
            panel = [[original[r][c] for c in range(c0, c1)] for r in range(r0, r1)]
            if not any(v != 0 for row in panel for v in row):
                continue
            targets = []
            if ci > 0:
                targets.append((ri, ci - 1, True, False))
            if ci + 1 < len(cs):
                targets.append((ri, ci + 1, True, False))
            if ri > 0:
