            if ri + 1 < len(rs):
                targets.append((ri + 1, ci, False, True))
            # Diagonal panels receive the reflection across both boundaries.
            for dr in (-1, 1):
                for dc in (-1, 1):
                    nr, nc = ri + dr, ci + dc
                    if 0 <= nr < len(rs) and 0 <= nc < len(cs):
                        targets.append((nr, nc, True, True))
            for nr, nc, flipx, flipy in targets:
                tr0, tr1 = rs[nr]
                tc0, tc1 = cs[nc]
                for y in range(r1 - r0):
                    for x in range(c1 - c0):
